## Inputs

```
export type ScaleComponentInputs = {
  /**
   * Markenbereich → Thumb-/Output-Farbe.
   *
   * @default co
   */
  area?: CdsArea;
  /**
   * Deaktiviert; auch über Angular-Forms (setDisabledState) steuerbar.
   *
   * @default false
   */
  disabled?: boolean; // two-way: [(disabled)]
  /** @default '' */
  helper?: string;
  /**
   * Feld-Label (die Frage), z. B. „Zufriedenheit“.
   *
   * @default Bewertung
   */
  label?: string;
  /**
   * Geordnete Skalen-Labels; sie sind zugleich die Werte.
   *
   * @default ['Niedrig', 'Mittel', 'Hoch']
   */
  labels?: string[];
  scaleId?: string;
  /**
   * Gewählte Stufe als Index (0-basiert). Two-Way (`[(value)]`) UND Angular-Forms.
   *
   * @default 1
   */
  value?: number; // two-way: [(value)]
}
```

## Outputs

```
export type ScaleComponentOutputs = {
  /** Deaktiviert; auch über Angular-Forms (setDisabledState) steuerbar. */
  disabledChange: (e: boolean) => void;
  /** Gewählte Stufe als Index (0-basiert). Two-Way (`[(value)]`) UND Angular-Forms. */
  valueChange: (e: number) => void;
}
```
